function addLiquidity(uint256 amtA, uint256 amtB) external {
  if (totalLPTokens == 0) {
    totalLPTokens = amtA;  // bootstrap: first deposit sets the ratio
  } else {
    uint256 mintA = (amtA * totalLPTokens) / reserveA;
    uint256 mintB = (amtB * totalLPTokens) / reserveB;
    totalLPTokens += mintA < mintB ? mintA : mintB;
  }
  reserveA += amtA; reserveB += amtB;
  lpBalance[msg.sender] += totalLPTokens;
}

function swapAForB(uint256 amtIn) external returns (uint256 out) {
  uint256 afterFee = amtIn * (10000 - 30) / 10000;  // 0.30% fee
  uint256 k = reserveA * reserveB;       // x*y=k invariant
  uint256 newResB = k / (reserveA + afterFee);
  out = reserveB - newResB;

  reserveA += amtIn;
  reserveB -= out;
}
